    if is_dst is not None:
        for fold in (0, 1):
            cand = naive.replace(tzinfo=zone, fold=fold)
            if (cand.dst() != timedelta(0)) == is_dst:
                return to_epoch(cand)
    return to_epoch(naive.replace(tzinfo=zone, fold=0))


