        cells = next(csv.reader([line]))
        cells = [c.strip() for c in cells]
        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        row = dict(zip(header, cells))
        month, day, year = row["Date"].split("/")
        tm = row["Time"].upper().split()
        hh, mm, ss = tm[0].split(":")
        hh, mm, ss = int(hh), int(mm), int(ss)
        if len(tm) > 1:
            hh = hh % 12 + (12 if tm[1] == "PM" else 0)
        naive = datetime(int(year), int(month), int(day), hh, mm, ss)
        abbr = row.get("Zone", "").upper()
        is_dst = True if abbr.endswith("DT") else False if abbr.endswith("ST") else None
        out.append((row["Record"], row["Badge"], row["Punch"].upper(), local_to_epoch(naive, zone, is_dst)))
    return out


def parse_epoch(lines, zone):
    out = []
    schema = 1
    for line in lines:
        obj = json.loads(line)
        if "schema" in obj and "id" not in obj and "punch_id" not in obj:
            schema = obj["schema"]
            continue
        if obj.get("heartbeat"):
            continue
        if schema == 2:
            ts = int(obj["epoch_ms"]) // 1000
            out.append((str(obj["punch_id"]), obj["employee"], obj["direction"].upper(), ts))
        else:
            if "ts_ms" in obj:
                ts = int(obj["ts_ms"]) // 1000
            else:
                ts = int(obj["ts"])
            out.append((str(obj["id"]), obj["emp"], obj["dir"].upper(), ts))
    return out


def parse_offset(lines, zone):
    out = []
    for row in csv.DictReader(io.StringIO("\n".join(lines)), delimiter=";"):
        ts = to_epoch(datetime.fromisoformat(row["timestamp"]))
        out.append((row["punch_id"], row["employee"], "IN" if row["event"] == "clock_in" else "OUT", ts))
    return out


def parse_legacy(lines, zone):
    out = []
    offset = None
    for line in lines:
        kind = line[0]
        if kind == "H":
            tail = line[13:18].strip()
            if tail:
                sign = -1 if tail[0] == "-" else 1
                offset = sign * timedelta(hours=int(tail[1:3]), minutes=int(tail[3:5]))
            else:
                offset = None
        elif kind == "D":
            stamp = datetime.strptime(line[16:30], "%Y%m%d%H%M%S").replace(tzinfo=UTC)
            if offset is None:
                guess = to_epoch(stamp)
                off = standard_offset(zone, guess - 12 * 3600)
                off = standard_offset(zone, guess - int(off.total_seconds()))
            else:
                off = offset
            ts = to_epoch(stamp) - int(off.total_seconds())
            out.append((line[1:9], "E" + line[9:15].strip(), "IN" if line[15] == "I" else "OUT", ts))
    return out


def parse_de(lines, zone):
    out = []
    header = None
    for line in lines:
        cells = [c.strip() for c in line.split("\t")]
        if "Ausweis" in cells:
            header = cells
            continue
        row = dict(zip(header, cells))
        day, month, year = row["Datum"].split(".")
        hh, mm = row["Uhrzeit"].split(":")[:2]
        naive = datetime(int(year), int(month), int(day), int(hh), int(mm))
        is_dst = row["Zeitzone"].upper() == "MESZ"
        out.append((row["Nr"], row["Ausweis"], "IN" if row["Buchung"] == "K" else "OUT",
                    local_to_epoch(naive, zone, is_dst)))
    return out


def parse_local_csv(lines, zone):
