        out.append((row["punch_ref"], row["employee_id"], row["direction"].strip().upper(),
                    local_to_epoch(naive, zone, True)))
    return out


def parse_local_jsonl(lines, zone):
    out = []
    for line in lines:
        punch = json.loads(line).get("punch")
        if not punch:
            continue
        naive = datetime.strptime(punch["at"], "%Y-%m-%d %H:%M:%S")
        out.append((str(punch["id"]), punch["badge"], punch["type"].upper(), local_to_epoch(naive, zone, True)))
    return out


