    last = from_epoch(end).astimezone(zone).date() + timedelta(days=1)
    day = first
    while day <= last:
        begin = local_to_epoch(datetime(day.year, day.month, day.day, 22), zone)
        nxt = day + timedelta(days=1)
        stop = local_to_epoch(datetime(nxt.year, nxt.month, nxt.day, 6), zone)
        total += max(0, min(end, stop) - max(start, begin))
        day = nxt
    return total


