                    exceptions["open_shifts"] += 1
                pending = (ts, direction, site, rounded)
            else:
                if pending is not None and rounded - pending[3] <= 16 * 3600:
                    shifts.append((pending, rounded))
                    pending = None
                else:
                    if pending is not None:
                        if in_period(pending[3]):
                            exceptions["open_shifts"] += 1
                        pending = None
                    if in_period(rounded):
                        exceptions["orphan_outs"] += 1
        if pending is not None and in_period(pending[3]):
            exceptions["open_shifts"] += 1

