                continue
            worked = max(0, (out_ts - in_ts) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(in_ts, out_ts, zones[inpunch[2]]) // 60, paid)
            rows.append({"in": in_ts, "day": workday(in_ts), "paid": paid, "night": night, "ot": 0})
        rows.sort(key=lambda r: r["in"])

        daily = {}
        for r in rows:
            before = daily.get(r["day"], 0)
            daily[r["day"]] = before + r["paid"]
            r["ot"] = max(0, before + r["paid"] - 480) - max(0, before - 480)
            r["nonot"] = r["paid"] - r["ot"]
        weekly = {}
        for r in rows:
            week = r["day"] - timedelta(days=r["day"].weekday())
            before = weekly.get(week, 0)
            weekly[week] = before + r["nonot"]
            r["ot"] += max(0, before + r["nonot"] - 2400) - max(0, before - 2400)

        res = result[emp]
        for r in rows:
            applicable = [rate for eff, rate in sorted(rates.get(emp, [])) if eff <= r["day"]]
            rate = applicable[-1] if applicable else Fraction(0)
            regular = r["paid"] - r["ot"]
            pay = rate * (regular + Fraction(3, 2) * r["ot"]) / 60 + rate * Fraction(15, 100) * r["night"] / 60
            res["shifts"] += 1
            res["paid_minutes"] += r["paid"]
            res["overtime_minutes"] += r["ot"]
            res["night_minutes"] += r["night"]
            res["gross"] += pay

    def cents(value):
        return (value * 100 + Fraction(1, 2)).__floor__()

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    total_cents = 0
    emps_out = {}
    for emp in sorted(result):
        res = result[emp]
        c = cents(res["gross"])
        total_cents += c
        for k in totals:
            totals[k] += res[k]
        emps_out[emp] = {k: res[k] for k in totals}
        emps_out[emp]["gross"] = "%d.%02d" % divmod(c, 100)
    totals["gross"] = "%d.%02d" % divmod(total_cents, 100)
    out = {"period": {"start": period["start"], "end": period["end"]}, "employees": emps_out,
           "exceptions": exceptions, "totals": totals}
    Path(outfile).parent.mkdir(parents=True, exist_ok=True)
    Path(outfile).write_text(json.dumps(out, indent=1))


